'use strict';
// Documents 14-24. v2.
const H = require('./helpers.js');
const { CO, CO_UP, FORMED, DEFILE, EIN, RA, ADDR, TALENT_DATE, REDEMPTION_DATE, AUTH_UNITS, RESERVE, VP, DVP, HIST, HIST_TOTAL, CONTRIB, SERVICE, CONTRIB_EACH, APPROX_TOTAL, APPROX_EACH, FOUNDERS, BROCK, CLASS_A, CLASS_B, OUTSTANDING, CEO, CTO, JGN_MEMBERS, N_FOUNDERS, RUPIA_FIRST, BROCK_DOC, TALENT_AMEND_DOC, RECEIPT_FIRST, RECEIPT_LAST, money, num, fdPct, outPct, votePct, vested, nbName, listAnd, FOUNDERS_AND, JGN_AND, doc, EFF, DEF_ONLY, DEFINED, kv, tbl, coSig, personSig } = H;

const JGN_TITLE = 'JGN MEDIA LLC PLATFORM CONTRIBUTION, BRAND LICENSE, FUNDING AND ACCOUNT TRANSITION AGREEMENT';
const JGN_TITLE_TC = 'JGN Media LLC Platform Contribution, Brand License, Funding and Account Transition Agreement';
const COMPANY_CTRL = CO + ' or Company-controlled administration';
const CONTRIB_AND = listAnd(CONTRIB.map(f => f.name));

// 14 Historical Company Operating Expense and JGN Contribution Schedule
function doc14() {
  const body = EFF +
  `<p>This schedule documents the Company's historical operating expenses from May 2026, when work on the Platform began, through November 2026. JGN Media LLC paid every one of them. No Founder paid any Company or Platform expense personally. The amounts are approximate and were compiled by the Chief Executive Officer from JGN's payment records, which control and which are available to every Member. JGN did not keep a separate expense ledger for the Platform; this schedule is that record.</p>` +
  tbl(['Expense', 'What it was for', 'How the amount is calculated', 'Approximate amount', 'Paid by'], HIST.map(h => [h.cat, h.what, h.math, money(h.amount), 'JGN'])
    .concat([['<strong>Total</strong>', '', HIST.map(h => money(h.amount)).join(' + '), '<strong>' + money(HIST_TOTAL) + '</strong>', 'JGN']]), 'hist') +
  tbl(['Contributing Founder', 'Share', 'Capital Contribution (' + money(HIST_TOTAL) + ' ÷ 4)'], CONTRIB.map(f => [nbName(f), '25%', APPROX_EACH]).concat([['<strong>Total</strong>', '<strong>100%</strong>', '<strong>' + APPROX_TOTAL + '</strong>']])) +
  kv([['Total recorded Company operating expenses', APPROX_TOTAL + ', May through November 2026'], ['Paid by JGN', 'All of them'], ['Paid by any Founder personally', 'None'], ['Treatment', 'The JGN Contribution through the Actual Closing Date: the Capital Contribution of the four Contributing Founders, one quarter each, under Operating Agreement Sections 3.4, 3.5 and 3.9 and Section 7 of the JGN Agreement'], ['Loan or repayment obligation', 'None. The Company owes none of these amounts to JGN or to any Member; contributed capital is returned only through distributions under Operating Agreement Section 10.5(a) or as the repurchase price of Units under Section 6.4'], ['Member liability', 'None. No reimbursement or share is owed by any Member, including the Service Founder and the Class B Member'], ['True-up', 'Amounts JGN paid before the Actual Closing Date that are not listed, and that JGN documents within 60 days after the Actual Closing Date, are added and credited in the same proportions (Operating Agreement Section 3.5)'], ['Future funding', 'Governed by Section 7 of the JGN Agreement']]) +
  `<p>Amounts JGN paid before the Company's formation on ${FORMED} were paid for the Platform and for the Company's benefit and are included. Payments under the Talent Agreement are not included in this schedule; Section 6 of the JGN Agreement governs them. The Platform has generated no revenue, so there is no revenue record to accompany this schedule.</p>` + coSig();
  return doc(14, 'HISTORICAL COMPANY OPERATING EXPENSE AND JGN CONTRIBUTION SCHEDULE', body);
}

// 15 Company Asset Schedule
function doc15() {
  const body = DEF_ONLY +
  `<p>This schedule identifies Company asset categories for record-book purposes, and the JGN-owned assets the Company uses under license. Specific repository, account and subscriber records are maintained in the Company's systems and updated after material changes.</p>` +
  tbl(['Asset category', 'Description', 'Ownership/control status'], [
    ['Corporate records', 'Operating Agreement, consents, ledgers, schedules, Founder agreements, JGN Agreement, Talent Agreement, contribution records, tax records and closing records.', 'Company'],
    ['Product and software', 'Source code, repositories, commits, branches, pull requests, issues, architecture, tests, integrations and deployment scripts of the Nosebleed Sports application, the website, the Discord bots and the data pipelines, assigned by JGN and the Founders at the Actual Closing Date.', 'Company'],
    ['Data assets', 'Company-created schemas, databases, metadata, analytics, picks records and grading history, subscriber and member records, operational datasets, logs, derived insights and documentation, subject to privacy law, platform and data-provider terms and third-party rights.', 'Company'],
    ['Commercial assets', 'Subscriber relationships of the Premium Offering once it launches, pricing models, product specifications and contract templates. No sponsorship or affiliate agreement relates to the Platform on the Actual Closing Date.', 'Company'],
    ['Community', 'The Nosebleed Sports Discord server, its channels, roles, bots and member base.', 'Company'],
    ['Accounts and infrastructure', 'Company-critical accounts and production infrastructure identified in the Company Account Schedule, held by JGN on the Actual Closing Date and transitioned under the JGN Agreement.', 'Company-owned or Company-controlled as commercially practical'],
    ['Brand License', 'The exclusive, perpetual, royalty-free, transferable license to use the Nosebleed Sports brand, and the domains that carry it, in the Field defined in the JGN Agreement.', 'Company (licensee); JGN owns the Brand'],
    ['Promotion covenant', 'JGN\'s covenant to promote the Platform and the Premium Offering through the Social Accounts under the JGN Agreement.', 'Company (beneficiary)'],
    ['Talent Agreement rights', 'The Company\'s rights as a Company Party under the Talent Agreement, including Work Product relating to the Platform and the Premium Offering and the services of the Class B Member.', 'Company (shared with JGN as the Talent Agreement allocates)'],
    ['JGN retained assets', 'The Nosebleed Sports brand and marks; the Social Accounts, their handles and their audiences; the domains that carry the Brand; historical content; all revenue, sponsorship, advertising and affiliate relationships of the Social Accounts; the other media brands and accounts of JGN\'s network; and JGN\'s general business systems, contracts and media technology.', 'JGN Media LLC'],
  ], 'w3') + coSig();
  return doc(15, 'COMPANY ASSET SCHEDULE', body);
}

// 16 IP Assignment Schedule and Chain of Title Register
function doc16() {
  const body = DEF_ONLY +
  `<p>This register maps Platform-specific intellectual property and technology assets to the documents that establish Company ownership, license rights and chain of title.</p>` +
  tbl(['Asset or contributor category', 'Chain-of-title instrument', 'Company right'], [
    ['Founder-created Platform-specific work, before and after the Actual Closing Date, including all Founder work on the app, the website and the Discord community', 'Founder PIIA (present assignment), supported by the Operating Agreement and the individual Founder Restricted Unit Issuance Agreement ("RUIA")', 'Present assignment to Company'],
    ['JGN-owned, JGN-funded or JGN-controlled Platform Assets, including the code', JGN_TITLE_TC + ' (the "JGN Agreement"); JGN Member Consent Approving Nosebleed Agreement', 'Present assignment to Company'],
    ['JGN background technology embedded in Platform assets', 'JGN Agreement (Section 3)', 'Perpetual, irrevocable, worldwide, fully paid, royalty-free, transferable, sublicensable, acquisition-surviving license'],
    ['The Nosebleed Sports brand and marks, and the domains that carry them', 'JGN Agreement (Brand License)', 'Exclusive in the Field, perpetual, royalty-free, transferable license, with a right to sublicense to service providers, app stores and platform partners; JGN retains ownership'],
    ['The Social Accounts and historical content', 'JGN Agreement (retained assets; promotion covenant)', 'Promotion of the Platform through the Social Accounts; no ownership'],
    ['Class B Member (Brock Smith) Work Product relating to the Platform and the Premium Offering', 'Talent Agreement Section 8.1 (present assignment); Work Product relating to the Brand and the Managed Accounts is assigned to JGN under the same Section', 'Present assignment to Company'],
    ['Current and former members of JGN', 'JGN Agreement Section 11: JGN represents that no former member holds any right, title or interest in the Platform Assets or the Brand; JGN\'s four members approve the assignment in the JGN Member Consent', 'No adverse interest; JGN representation'],
    ['Any other contractor or creator who worked on the Platform, its data pipelines or its content before the Actual Closing Date', 'Written IP assignment to the Company (or to JGN, assigned onward under the JGN Agreement); none is on file in this record book as of the Actual Closing Date, and JGN represents in the JGN Agreement that no former member and no contractor holds any right, title or interest in the Platform Assets or the Brand', 'Assignment to Company if and when signed'],
    ['Future employees, contractors, consultants, developers and advisors', 'Company-approved PIIA, service-provider, contractor or developer agreement signed at engagement', 'Assignment or license upon signature'],
    ['Open-source, sports-data, odds and other third-party materials', 'Company records and third-party license and provider terms', 'Licensed rights only, subject to license and provider terms'],
    ['Company accounts and repositories', 'Operating Agreement, JGN Agreement, Company Account Schedule and access-control records', 'Company ownership or Company-controlled administration as commercially practical'],
  ]) +
  tbl(['Member', 'Assignment status', 'Related documents'], FOUNDERS.map(f => [nbName(f), 'Assigned to Company by execution of closing documents', 'Founder PIIA; RUIA; Operating Agreement']).concat([[nbName(BROCK), 'Assigned under the Talent Agreement, effective on creation', 'Talent Agreement Section 8.1; Class B Unit Issuance Record']])) + coSig();
  return doc(16, 'IP ASSIGNMENT SCHEDULE AND CHAIN OF TITLE REGISTER', body);
}

// 17 Company Account Schedule
function doc17() {
  const cats = [
    'Source-code repositories for the app, the website, the Discord bots and the data pipelines',
    'Hosting, storage and deployment platforms and production infrastructure',
    'Databases, authentication and user-management services',
    'Transactional email and messaging services',
    'Analytics, error-monitoring and logging services',
    'The Company\'s Discord server (server ownership, administrator roles, bots and role integrations)',
    'Subscription, payment and payout platforms for the Premium Offering',
    'App-store developer accounts',
    'Sports-data and odds-data API accounts (account names and owners only; no credentials or keys)',
    'AI tool and developer tool accounts used for the Platform',
    'Password manager',
    'Google Workspace, email and shared drives used for Company work',
  ];
  const body = DEF_ONLY +
  `<p>An account in any category below is Company-critical if it is used for Company work or holds Company assets. On the Actual Closing Date each of these accounts is held by JGN Media LLC, or by a Founder for JGN, and is transitioned under Section 9 of the JGN Agreement. Company-critical accounts shall belong to ${CO} or be under Company-controlled administration, and no Founder may permanently own a Company-critical account in a personal capacity. Control standard for every Company-critical account: multi-factor authentication, password-manager control, preserved audit history and, where practical, at least two Company-approved administrators. No credential, API key or recovery code is recorded in this schedule or anywhere in the record book, and no credential or API key is rotated, cancelled or regenerated except as the Chief Technology Officer approves or Section 4.8 of the Operating Agreement provides.</p>` +
  tbl(['Account category', 'Required owner or controller'], cats.map(c => [c, COMPANY_CTRL]).concat([
    ['Company business checking account to be opened at Chase under the Banking Resolution (last four digits recorded here when opened); sole signer: the Chief Executive Officer', CO + ' (Company bank account)'],
    ['Other banking and finance systems', COMPANY_CTRL],
  ])) +
  `<p class="note">Social Accounts and Brand domains: the Nosebleed Sports TikTok and Instagram accounts and the other social media accounts and handles of JGN's media network, including the accounts the Class B Member manages under the Talent Agreement, and the domains that carry the Brand, are owned by JGN Media LLC, are not Company Accounts and are not transferred. The Company uses those domains for the Platform under the Brand License, and its interest in the Social Accounts is the promotion covenant in the JGN Agreement.</p>
<p class="note">Platform exception note: if a vendor does not permit legal transfer of an account, the responsible officer must document the exception and establish commercially equivalent Company control, export rights, administrative access and audit-history preservation where available. Accounts that JGN holds for the Company pending transition are recorded with their current controller and target date.</p>` + coSig();
  return doc(17, 'COMPANY ACCOUNT SCHEDULE', body);
}

// 18 Founder PIIA
function doc18() {
  const body = `<p>This Agreement (the "Founder PIIA") is entered into as of the Actual Closing Date by ${CO} and each Founder listed on the signature pages. ${DEFINED}</p>
<h2>1. PURPOSE</h2>
<p>This Agreement confirms each Founder's confidentiality, invention-assignment, data-security, account-control and acquisition-cooperation obligations. It supports the Company's IP chain of title and does not change ownership percentages, vesting, voting thresholds, distributions, officer titles or Capital Contributions.</p>
<h2>2. COMPANY IP AND CONFIDENTIAL INFORMATION</h2>
<p>Company IP has the meaning given in the Operating Agreement, does not include an Excluded Project (Section 3), the Brand, the Social Accounts or JGN's retained assets, and includes all Platform-specific inventions, works of authorship, software, source code, repositories, commits, databases, schemas, data structures, data pipelines, odds and scores adapters, picks tracking and grading logic, Discord bots and automations, integrations, product designs, documentation, prompts, internal tooling, APIs, configurations, deployment pipelines, infrastructure, tests and related know-how.</p>
<p>Confidential Information has the meaning given in the Operating Agreement and includes all non-public Company information, including product plans, architecture, subscriber and member records, picks methodology and unpublished picks, pricing, contracts, sponsorship and data-provider terms, payment information, credentials, MFA, recovery methods, source code, databases, analytics, vendor terms, the terms of the Talent Agreement and the JGN Agreement, acquisition discussions and security materials.</p>
<h2>3. PRESENT ASSIGNMENT; EXCLUDED PROJECTS; CONNECTED PROJECTS</h2>
<p>Each Founder hereby assigns to the Company all right, title and interest worldwide in all Company IP (which does not include an Excluded Project) that the Founder owns or controls, whether created before or after the Actual Closing Date, including all copyrights, patent rights, trade secrets, database rights, mask works, moral rights to the extent assignable or waivable, rights of action, proceeds and recoveries. This assignment includes everything each Founder did on the app, the website and the Discord community before the Actual Closing Date, whether or not JGN funded it and whether or not the Founder had signed any earlier agreement about it.</p>
<p>Anything created for the Company or in connection with the Company Business belongs exclusively to the Company, except an Excluded Project, work that the Talent Agreement or the JGN Agreement allocates to JGN, and work a Founder does after Continuous Service ends without using Company IP or Confidential Information. Ordinary work of a business that meets the conditions of Section 11.5(ii) or (iii) of the Operating Agreement, including work for JGN's retained media business, is not in connection with the Company Business unless it uses Company IP or Confidential Information. An "Excluded Project" is work, a project or a business that a Founder develops entirely on the Founder's own time, without using Company equipment, Company Accounts, Company Data, Company source code, Company IP or Confidential Information, that does not result from work the Founder performed for the Company, and that, when the Founder created or began it, was not a product or service of the same kind as either one the Company then offered or one then listed in Schedule F to the Operating Agreement as a Company product. An Excluded Project remains the Founder's property. A Founder is not required to disclose or list an Excluded Project unless it is also a Connected Project under the next paragraph, and the Company's later plans do not change its status. A Founder may put an Excluded Project on record by written notice to the Company through an Official Channel, in which case the project is treated for purposes of this Section as created or begun no later than the date of that notice. If part of an Excluded Project later uses Company resources of the kinds listed above or builds on Company IP, that part is Company IP and the rest of the project remains an Excluded Project. Information, accounts or materials that an outside project receives in an arm's-length dealing with the Company that was approved as the Operating Agreement requires, and uses only for that dealing, are not use of Company resources under this Section.</p>
<p>A Founder shall disclose to the Company in writing through an Official Channel each outside work, project or business of the Founder, and each position or interest of the Founder in another business, other than JGN, that (a) uses Company equipment, Company Accounts, Company Data, Company source code, Company IP or Confidential Information, (b) receives money from, pays money to, or otherwise does business with the Company, or (c) is a Competing Business under Section 11.5 of the Operating Agreement or is, or includes, a product or service of the same kind as either one the Company offers or one listed in Schedule F to the Operating Agreement as a Company product, other than a business that meets the conditions of Section 11.5(ii) or (iii) of the Operating Agreement (a "Connected Project"). Disclosure is due within 30 days after the Actual Closing Date for a connection that exists on that date, and otherwise within 30 days after the connection first arises, and must describe the project and the connection in enough detail to identify them. Disclosure does not change who owns a Connected Project or any part of it; ownership is determined under this Section. Disclosure also does not by itself approve a Connected Project or any dealing between it and the Company; the Operating Agreement's Company Opportunity and competition rules (Sections 11.1 and 11.5) and its related-party approval requirements (Schedule B) apply. JGN's dealings with the Company are governed by the JGN Agreement and need no separate disclosure under this Section.</p>
<p>Materials unrelated to the Company and the Company Business remain owned by their proper owner, subject to the Operating Agreement, the JGN Agreement and any written license approved by the Company.</p>
<h2>4. SEPARATE ENFORCEABILITY</h2>
<p>The Founder's Capital Contribution or services for Class A Units do not reduce, waive, replace or satisfy the Founder's IP assignment, confidentiality, data-security, account-control, founder-duty, restrictive-covenant or acquisition-cooperation obligations. Founder IP assignments do not increase Unit allocations or change ownership percentages.</p>
<h2>5. PRIOR INVENTIONS AND JGN BOUNDARY</h2>
<p>No Founder excludes any Platform-specific work from this assignment. The Brand, the Social Accounts, JGN retained assets and JGN background technology are handled by the JGN Agreement. A Founder's work that is not Company IP, including an Excluded Project, may not be used in Company products without Company approval and, if required, a written license.</p>
<h2>6. CONFIDENTIALITY AND DATA USE</h2>
<p>Each Founder shall use Confidential Information only for Company purposes and shall protect it using commercially reasonable safeguards. Confidential Information, Company Data, subscriber and member records, unpublished picks and picks methodology, source code, prompts, payment information, security materials and acquisition-sensitive materials may not be used to train, fine-tune, evaluate or improve third-party AI models, external machine-learning systems or external analytics systems, or to operate any picks, content or community product outside the Company, without Company approval. This paragraph does not reach an Excluded Project, other property of the Founder, or JGN's retained media business.</p>
<p>Notice under 18 U.S.C. Section 1833(b): an individual will not be held criminally or civilly liable under any federal or state trade-secret law for disclosing a trade secret (a) in confidence to a federal, state or local government official, or to an attorney, solely for the purpose of reporting or investigating a suspected violation of law, or (b) in a complaint or other document filed under seal in a lawsuit or other proceeding. An individual who files a retaliation lawsuit for reporting a suspected violation of law may disclose the trade secret to the individual's attorney and use it in the court proceeding if the individual files any document containing the trade secret under seal and does not disclose it except under court order.</p>
<h2>7. COMPANY ACCOUNTS AND SECURITY</h2>
<p>Each Founder shall use Company-approved accounts, MFA, secure credentials, approved password-manager controls and least-privilege access for Company work. No Founder may withhold, delete, disable, conceal, lock out, hold hostage, impair or use Company Accounts, credentials, API keys, repositories, logs, deployments, databases, the Discord server or vendor systems as leverage in any dispute, and no Founder may rotate, cancel or regenerate a credential or API key used by the Platform except as the Chief Technology Officer approves or Section 4.8 of the Operating Agreement provides.</p>
<h2>8. RETURN, PRESERVATION AND ACQUISITION COOPERATION</h2>
<p>Upon Company request or departure, each Founder shall return, transfer or delete as directed all Company property, Company Data, Company Accounts, credentials, source code, repositories, prompts, subscriber materials, picks records, payment data, screenshots, backups, local clones and personal-drive copies, other than an Excluded Project or other property of the Founder. Each Founder shall reasonably cooperate in acquisition diligence, source-code review, IP confirmation, security review, privacy review, account transfer, disclosure schedules and closing.</p>
<h2>9. GENERAL</h2>
<p>This Agreement is governed by the laws of the State of Delaware without regard to conflict-of-laws rules, and disputes under it are subject to the forum provisions of Section 16.4 of the Operating Agreement. This Agreement may be signed in counterparts and by electronic signature, each of which is an original. If any provision is held unenforceable, it shall be reformed to the minimum extent necessary and the remainder enforced.</p>
<div class="sigpage"><h2>SIGNATURE PAGE</h2>` + coSig('Company') + FOUNDERS.map(f => personSig(f.name, 'Founder; Class A Member; ' + f.office)).join('') + `</div>`;
  return doc(18, 'FOUNDER PROPRIETARY INFORMATION, IP ASSIGNMENT AND DATA SECURITY AGREEMENT', body, { footTitle: 'FOUNDER PIIA' });
}

// 19 JGN Agreement
function doc19() {
  const body = `<p>This Agreement (the "JGN Agreement") is entered into as of the Actual Closing Date by and between ${CO} (the "Company") and JGN Media LLC, a New York limited liability company ("JGN"). ${DEFINED}</p>
<p>In consideration of the mutual covenants in this Agreement and other good and valuable consideration, the receipt and sufficiency of which are acknowledged, the parties intend to transfer the Platform's code and everything else created specifically for the Platform to the Company; to license the Nosebleed Sports brand to the Company and commit the audience of the Social Accounts to the Platform's growth; to record that the money JGN has spent and will spend on the Company is the capital contribution of JGN's four members and not a loan; and to preserve JGN's ownership of the brand, the Social Accounts and its other media business.</p>
<h2>1. DEFINITIONS</h2>
<p>1.1 "Brand" means the "Nosebleed Sports" name, the Nosebleed Sports word marks and logos, the related names, logos, domains, trade dress and goodwill, and the names and marks of the Company's products that incorporate them (including "Nosebleed Live"), all owned by JGN.</p>
<p>1.2 "Social Accounts" means the Nosebleed Sports social media accounts on TikTok, Instagram, X, YouTube and every other platform, the other accounts of JGN's sports media network (including its sub-brand accounts), their handles, followers and audiences, the content published on them, and the creator-program, monetization and advertising relationships attached to them, all owned by JGN. The Social Accounts include the Managed Accounts under the Talent Agreement.</p>
<p>1.3 "Platform Assets" means the Platform and all Platform-specific code, repositories and their histories, backends, APIs, database schemas and data, data pipelines, odds and scores adapters, picks records and grading logic, Discord server configuration, bots and role integrations, subscription and payment integrations, prompts and automations, internal tooling, documentation, configurations, deployment scripts, infrastructure, designs, product specifications, and subscriber and member records of the Platform, in each case that JGN owns or controls, including everything the Founders built with JGN's funding. The Platform Assets do not include the Brand or the Social Accounts.</p>
<p>1.4 "Field" means apps, websites, online and messaging communities (including Discord), fantasy sports leagues and games, subscription and membership products, paid picks, props, handicapping and analysis offerings, live sessions sold as part of them, and related digital products, tools and services offered to consumers under the Brand, together with sponsorship, advertising and affiliate placements within them.</p>
<p>1.5 "Reserved Field" means the Social Accounts, social, video and audio content published through them or through other media channels, newsletters and podcasts, free content and commentary of every kind, the sale of advertising, sponsorships, brand deals and affiliate placements on the Social Accounts and other media channels, merchandise, events not sold as part of the Premium Offering, and JGN's other media business, in each case under the Brand or otherwise.</p>
<p>1.6 "JGN Contribution" has the meaning given in the Operating Agreement.</p>
<p>1.7 "Self-Sufficiency Date" means the first day after the Company has, for three consecutive calendar months, collected operating cash receipts into Company accounts that exceed its operating expenses for each of those months, and holds cash in Company accounts equal to at least three months of its then-budgeted operating expenses, as determined by the Chief Executive Officer and confirmed in writing by JGN, which confirmation JGN shall not unreasonably withhold.</p>
<h2>2. PRESENT ASSIGNMENT OF PLATFORM ASSETS</h2>
<p>JGN hereby assigns to the Company all right, title and interest worldwide in the Platform Assets, including the code. Before this assignment JGN owned the code, which began as the work of ${CEO.name} and was funded by JGN. The assignment is part of the JGN Contribution, made on behalf of JGN's four members, and the parties assign it no value separate from the amounts JGN paid to build the Platform Assets. Ownership, payment or administration of a subscription, account, repository, tool or vendor relationship by JGN after the Actual Closing Date does not affect the Company's ownership of the Platform Assets.</p>
<h2>3. JGN RETAINED ASSETS</h2>
<p>JGN retains the Brand, the Social Accounts and their handles, the domains that carry the Brand, the Reserved Field, all content published on the Social Accounts before and after the Actual Closing Date, all revenue of the Social Accounts and its sponsorship, advertising, affiliate and creator-program relationships for them, its other media brands, accounts, customers, content and contracts, its general business systems, and background tools and technology not created specifically for the Platform. To the extent any of that background technology is embedded in, necessary for or used with the Platform Assets and is not assigned to the Company, JGN grants the Company a perpetual, irrevocable, worldwide, fully paid, royalty-free, transferable, sublicensable license, which survives any Change of Control, to use, reproduce, modify and create derivative works from it as part of the Platform. This Agreement licenses the Brand. It does not sell, assign or transfer the Brand, any right of ownership in the Brand, any Social Account or any handle to the Company or to anyone else.</p>
<h2>4. BRAND LICENSE</h2>
<p>4.1 Grant. JGN grants the Company an exclusive (including as against JGN), worldwide, perpetual, irrevocable except as Section 4.6 provides, fully paid, royalty-free license to use, reproduce, display and otherwise exploit the Brand in the Field, including in the names of the Company's products, in app stores, on the website, in the Discord community, in the Premium Offering, and in the Company's advertising, marketing and promotion of the Field, with the right to sublicense to the Company's service providers, distributors, app stores and platform partners for those purposes (the "Brand License"). The Brand License includes the exclusive right to operate the Platform on the domains that carry the Brand and that the parties designate for the Platform; JGN remains their registrant and owner, keeps them registered and renewed, and manages their DNS records as the Company directs for the Platform or delegates that management to the Company; no domain is transferred. JGN reserves the Reserved Field and all uses of the Brand outside the Field. JGN shall not use, and shall not license or permit any other Person to use, the Brand or any confusingly similar name or mark in the Field.</p>
<p>4.2 Quality control. The Company shall use the Brand in the Field in a manner consistent with the quality, tone and reputation of the Nosebleed Sports media network, in compliance with applicable law and platform terms, and in accordance with reasonable written brand guidelines JGN provides from time to time that do not restrict the Company's products or pricing. On JGN's reasonable request, no more than twice a year, the Company shall provide representative samples of its use of the Brand. JGN may require correction of a use that materially departs from the guidelines, and the Company shall correct it within 30 days after written notice.</p>
<p>4.3 Ownership and goodwill. JGN owns the Brand, and all goodwill arising from the Company's use of the Brand inures to JGN. The Company shall not register, claim or challenge any right in the Brand or any confusingly similar name, mark, handle or domain, other than app-store listings held as licensee under this Agreement, and shall cooperate with JGN's registration and enforcement of the Brand. JGN shall maintain its registrations and enforce the Brand against infringers in the Field at the Company's reasonable request, and, if JGN declines, the Company may enforce in its own name at its cost.</p>
<p>4.4 Transferability; Change of Control. The Brand License is an asset of the Company. It may be assigned by the Company, without JGN's consent, to a successor to the Company Business in a Change of Control or sale of substantially all of the Company's assets, and continues after that transaction on the same terms. JGN shall, within 10 business days after the Company's request in connection with a proposed Change of Control, deliver to the Company and the proposed acquirer a written confirmation that the Brand License is in effect, that no default exists (or stating any claimed default), and that the Brand License will continue in favor of the acquirer.</p>
<p>4.5 Sale of the Brand; first offer. Any sale, assignment or exclusive license of the Brand by JGN, and any lien on it, is subject to the Brand License, and JGN shall cause the transferee to assume this Section 4 in writing. Before JGN agrees to sell or assign the Brand to any Person other than an Affiliate that assumes this Agreement, JGN shall offer the Brand to the Company in writing on the price and terms JGN proposes, and the Company shall have 45 days to accept; if the Company declines or does not respond, JGN may sell on terms no more favorable to the buyer within 180 days. Any sale of the Brand, to the Company or anyone else, is at fair market value and is JGN's decision under its own agreements.</p>
<p>4.6 Termination. The Brand License may be terminated by JGN only (a) if the Company ceases all use of the Brand in the Field for 24 consecutive months, or (b) on a final, non-appealable judgment that the Company materially breached Section 4.2 and failed to cure within 90 days after written notice. The Brand License does not terminate on the Company's insolvency, on a breach of any other agreement, on the end of JGN's funding commitment, or on a change in the ownership of JGN or the Company. On any termination, the Company has 12 months to transition away from the Brand.</p>
<h2>5. PROMOTION COVENANT</h2>
<p>5.1 Promotion. For so long as the Brand License is in effect, JGN shall promote the Platform and the Premium Offering through the Social Accounts as the primary destination for the Nosebleed Sports audience, including by maintaining the Platform's link in the profiles of the Nosebleed Sports Social Accounts, publishing promotional posts, stories and live sessions on a regular cadence agreed between the Chief Executive Officer and JGN each quarter, and featuring the Platform in the Managed Accounts' content under the Talent Agreement. JGN charges the Company nothing for this promotion. JGN shall not promote through the Social Accounts any product that is a Competing Business under Section 11.5 of the Operating Agreement.</p>
<p>5.2 Audience data. Follower and audience data of the Social Accounts belongs to JGN. JGN shall share with the Company the aggregate analytics reasonably needed to measure the promotion covenant and the Platform's funnel.</p>
<p>5.3 After a Change of Control. The promotion covenant continues for 24 months after the closing of a Change of Control on the terms then in effect, for the benefit of the successor to the Company Business, unless the successor and JGN agree otherwise in writing.</p>
<h2>6. TALENT AGREEMENT ALLOCATION</h2>
<p>As between the Company Parties under the Talent Agreement, JGN performs the obligations and holds the rights that relate to the Brand and the Managed Accounts, and the Company performs the obligations and holds the rights that relate to the Platform and the Premium Offering. Each Company Party honors the Contractor's equity in Section 5 of the Talent Agreement through Section 3.7(b) of the Operating Agreement. Until the Self-Sufficiency Date JGN pays the Contractor's Monthly Fee, bonuses and revenue shares; those payments are JGN's own expense, and are a JGN Contribution only to the extent JGN and the Company record in writing that a payment is for the Platform or the Premium Offering. Brand Deal Revenue and Qualifying Revenue under the Talent Agreement are allocated between JGN and the Company under Section 8, and the Company Parties shall prepare the Contractor's monthly statement jointly.</p>
<h2>7. JGN CONTRIBUTIONS</h2>
<p>7.1 Historical funding. JGN has paid every operating expense of the Company and the Platform through the Actual Closing Date, ${APPROX_TOTAL} from May through November 2026, as itemized in Schedule C to the Operating Agreement. JGN shall keep its bank, card and vendor payment records for those expenses, make them available to any Member on request, and document to the Members within 60 days after the Actual Closing Date any other amount it paid for the Company before that date.</p>
<p>7.2 Funding commitment. Until the Self-Sufficiency Date, JGN shall fund the Company's operating expenses that are approved within the spending authority in Section 4.3 of the Operating Agreement and included in a quarterly operating budget that JGN approves in writing, by depositing funds into the Company's bank account or paying vendors directly, and shall record each amount by date, payee and purpose and report it to the Company and every Class A Member at least quarterly. JGN may decline to approve a budget or an item in it. JGN may end this commitment on 90 days' written notice, approved by JGN's members and delivered to the Company and every Class A Member through an Official Channel, and the commitment ends automatically on the Self-Sufficiency Date and at the closing of a Change of Control.</p>
<p>7.3 Capital, not a loan. Every amount JGN pays under Sections 7.1 and 7.2 is a JGN Contribution: a capital contribution to the Company made by JGN on behalf of its members who are Contributing Founders, credited to their Capital Accounts and Unreturned Capital as Section 3.9 of the Operating Agreement provides, initially one quarter each. No JGN Contribution is a loan. None bears interest. The Company has no obligation to repay any of it, and neither the Company nor any Member owes JGN anything for it. Contributed capital is returned only to the Contributing Founders, and only through distributions under Section 10.5(a) of the Operating Agreement, including from the proceeds of a Change of Control, or as the repurchase price of Units under Section 6.4 of the Operating Agreement. How JGN and its members account between themselves for a JGN Contribution is a matter for JGN.</p>
<p>7.4 No equity, security or control. JGN Contributions give JGN no Units, no right to Units, no security interest, no lien, no vote and no right to control the Company. JGN's approval right under Section 7.2 is a funding decision only.</p>
<h2>8. REVENUE ALLOCATION</h2>
<p>Subscription, membership, premium-tool, Platform sponsorship, Platform affiliate and other revenue of the Field belongs to the Company. Advertising, sponsorship, brand-deal, affiliate, creator-program and monetization revenue of the Reserved Field belongs to JGN. All revenue received before the Actual Closing Date came from the Social Accounts and belongs to JGN; the Platform has generated none. The Company shall collect Field revenue directly, in bank, subscription and payment accounts held in its own name, and JGN shall not collect Field revenue for the Company. If JGN nevertheless receives an amount that is Field revenue, it receives that amount as the Company's agent, holds it in trust for the Company, does not treat it as JGN's own receipt, and remits it to the Company's bank account within 10 days. Where a single arrangement spans the Field and the Reserved Field, the parties contract and invoice the two elements separately where practicable and otherwise allocate the revenue in good faith by the relative value of the elements, as Section 4.2 of the Talent Agreement provides for the Contractor's share.</p>
<h2>9. COMPANY ACCOUNTS; CREDENTIALS; AUDIT HISTORY</h2>
<p>On the Actual Closing Date JGN, or a Founder for JGN, holds the accounts the Platform runs on. JGN shall preserve the Company's access to the Company Accounts, avoid unilateral lockout, transfer to the Company the ownership or administrative control of each Company Account as commercially practical and in any event before the closing of a Change of Control, preserve commit history and audit logs where available, and maintain at least two Company-approved administrators for critical systems where practical. Credentials and API keys are transferred, and changed only as the Company's Chief Technology Officer approves or Section 4.8 of the Operating Agreement provides; nothing in this Agreement requires or permits any other rotation, cancellation or regeneration of a credential or API key the Platform uses. No Social Account, handle or Brand domain is transferred. The Company shall preserve JGN's access to the Social Accounts and shall not claim any right in them.</p>
<h2>10. NO EQUITY EFFECT</h2>
<p>This Agreement does not alter Founder Unit allocations, vesting, ownership percentages or governance rights. JGN is not a Member and receives no Units under this Agreement. ${H.SERVICE.name} and the Class B Member have no interest in JGN and no right to participate in JGN's decisions.</p>
<h2>11. JGN REPRESENTATIONS; FURTHER ASSURANCES</h2>
<p>JGN represents that it has full power and authority to enter into and perform this Agreement; that its members, being ${JGN_AND} and no one else, have unanimously approved this Agreement by the JGN Member Consent Approving Nosebleed Agreement (the "JGN Member Consent"); that it owns the Platform Assets and the Brand free of liens, licenses in the Field and other encumbrances, other than platform terms and the Talent Agreement; that no former member of JGN and no contractor holds any right, title or interest in the Platform Assets or the Brand; that this Agreement does not breach any agreement of JGN, including any agreement with a current or former member; that JGN does not enter into this Agreement to hinder, delay or defraud any creditor and remains able to pay its debts as they come due after giving effect to it; and that the amounts in Schedule C to the Operating Agreement are accurate in all material respects.</p>
<p>JGN's debts and its obligations to its current and former members are JGN's alone. The Company assumes none of them, and JGN shall keep the Company and the Platform Assets free of, and indemnify the Company against, any claim arising from them.</p>
<p>JGN shall sign documents and provide reasonable assistance requested to confirm, perfect, enforce or transfer the Company's rights, including in acquisition diligence, source-code review, IP confirmation, Brand License confirmation under Section 4.4, account transfer and closing.</p>
<h2>12. COMPETITION</h2>
<p>During any period in which a member of JGN is within that member's Restricted Period under Section 11.5 of the Operating Agreement, JGN shall not, directly or indirectly, do anything that Section prohibits a Founder from doing, subject to the same exceptions, and shall not license the Brand or its background technology to, or promote through the Social Accounts, a Competing Business as defined in that Section. This does not restrict the Reserved Field, so long as that business is not itself a Competing Business and does not help build, run or scale one.</p>
<h2>13. GENERAL</h2>
<p>This Agreement is governed by the laws of the State of Delaware without regard to conflict-of-laws rules, and disputes under it are subject to the forum provisions of Section 16.4 of the Operating Agreement. ${CEO.name} signs this Agreement for both parties, as Chief Executive Officer of each, under the unanimous Initial Member and Organizational Written Consent of the Company and the unanimous JGN Member Consent. This Agreement may be amended only by a writing signed by both parties and approved as a Major Decision under Schedule B to the Operating Agreement and by JGN's members. It may be signed in counterparts and by electronic signature, each of which is an original. If any provision is held unenforceable, it shall be reformed to the minimum extent necessary and the remainder enforced. Sections 2, 3, 4, 5.3, 6, 7.3, 7.4, 8, 9, 10 and 11 survive any termination of JGN's funding commitment and any Change of Control.</p>
<div class="sigpage"><h2>SIGNATURE PAGE</h2>` +
  `<div class="sig"><p class="who">${CO}</p><p>By: _________________________________________</p><p>Name: ${CEO.name}</p><p>Title: ${CEO.office}</p><p>Date signed: __________________________________</p></div>` +
  `<div class="sig"><p class="who">JGN Media LLC</p><p>By: _________________________________________</p><p>Name: ${CEO.name}</p><p>Title: Chief Executive Officer</p><p>Date signed: __________________________________</p></div></div>`;
  return doc(19, JGN_TITLE, body, { footTitle: 'JGN AGREEMENT', h1: JGN_TITLE });
}

// 20 JGN Member Consent
function doc20() {
  const body = `<p>The undersigned members of JGN Media LLC approve JGN's execution and performance of the JGN Media LLC Platform Contribution, Brand License, Funding and Account Transition Agreement with ${CO} (the "JGN Agreement"). This consent is effective upon signature; the JGN Agreement becomes effective as of the Actual Closing Date. Capitalized terms used but not defined in this consent have the meanings given in the Limited Liability Company Agreement of ${CO} (the "Nosebleed Operating Agreement") and in the JGN Agreement.</p>
<p>The undersigned are all of the members of JGN Media LLC. Each of them holds twenty-five percent (25%) and together they hold one hundred percent (100%) of JGN's membership interests, which meets every approval threshold under the JGN Media LLC operating agreement for each action approved in this consent.</p>
<p>This approval includes the present assignment of the Platform Assets, including the code, to ${CO}; the exclusive, perpetual, royalty-free, transferable Brand License in the Field; the promotion covenant; the allocation of the Talent Agreement between JGN and ${CO} and JGN's signature of the First Amendment to the Talent Agreement; JGN's funding commitment under Section 7.2 of the JGN Agreement, which JGN may end on 90 days' notice approved by JGN's members; the revenue allocation; the account transition; and JGN's competition covenant in Section 12 of the JGN Agreement.</p>
<p>The undersigned approve treating every amount JGN has paid and pays for ${CO}, ${APPROX_TOTAL} through the Actual Closing Date, as a capital contribution to ${CO} made by JGN on their behalf in equal shares, ${APPROX_EACH} each to date, in exchange for the Class A Units ${CO} issues to them. They confirm that none of it is a loan, that JGN has no claim against ${CO} or any of its members for repayment, and that contributed capital is returned only to them, through distributions and the repurchase of Units under the Nosebleed Operating Agreement.</p>
<p>The undersigned confirm that the JGN Agreement licenses the Brand and does not sell, assign or transfer the Brand, any Social Account or any handle; that the Platform Assets and anything created specifically for the Platform belong exclusively to ${CO} from the Actual Closing Date; that the Brand, the Social Accounts and JGN's other assets remain the sole property of JGN Media LLC, subject to the Brand License and the promotion covenant; and that JGN's debts and its obligations to its current and former members remain JGN's alone.</p>
<p>The undersigned authorize ${CEO.name}, Chief Executive Officer of JGN Media LLC, to execute the JGN Agreement and the First Amendment to the Talent Agreement on behalf of JGN Media LLC, and acknowledge that he also signs both for ${CO} as its Chief Executive Officer. If he is unable to act, any two of the undersigned may sign for JGN Media LLC any confirmation, notice, approval or other document the JGN Agreement calls for.</p>
<p>This consent does not otherwise alter ${CO} Unit allocations, Capital Accounts, vesting or governance rights.</p>` +
  JGN_MEMBERS.map(f => personSig(f.name, 'Member of JGN Media LLC (25%)')).join('');
  return doc(20, 'JGN MEMBER CONSENT APPROVING NOSEBLEED AGREEMENT', body, { company: 'JGN MEDIA LLC', h1: 'JGN MEMBER CONSENT APPROVING NOSEBLEED AGREEMENT' });
}

// 21 Closing Checklist and Signature Index
function doc21() {
  const ruiaRange = `${RUPIA_FIRST} through ${RUPIA_FIRST + N_FOUNDERS - 1}`;
  const receiptRange = `${RECEIPT_FIRST} through ${RECEIPT_LAST}`;
  const ruiaOf = f => RUPIA_FIRST + FOUNDERS.indexOf(f);
  const receiptOf = f => RECEIPT_FIRST + CONTRIB.indexOf(f);
  const steps = [
    ['Make JGN\'s payment records for the listed expenses available to all Members, and review the Historical Company Operating Expense and JGN Contribution Schedule', 'Chief Executive Officer; Company and Members'],
    ['Review the completed Factual Valuation Worksheet in the FMV Memorandum and confirm no contradictory valuation facts', 'Company and Members'],
    ['Approve FMV Memorandum', 'All Class A Members'],
    ['Execute Organizational Consent', 'All Class A Members'],
    ['Execute Operating Agreement', 'All Class A Members; the Company signs at step 13'],
    ['Execute Founder RUIAs', 'Each Founder; the Company signs at step 13'],
    ['Execute Founder PIIA', 'Company and all Founders'],
    ['Execute JGN Member Consent', `All four JGN members (${JGN_MEMBERS.map(f => f.last).join(', ')})`],
    ['Execute JGN Agreement', `${CO} and JGN Media LLC, each by its Chief Executive Officer`],
    [`Deliver a copy of the Operating Agreement to Brock Smith, then execute the First Amendment to the Talent Agreement (document ${TALENT_AMEND_DOC})`, 'JGN Media LLC, the Company and Brock Smith'],
    ['Before the contributions are recorded, confirm that no later facts contradict the FMV Memorandum', 'Chief Executive Officer'],
    [`Record each Contributing Founder's Capital Contribution, and the dates and supporting-records references, in documents 04 through 06, the Contributing Founders' RUIAs and documents ${receiptRange}`, 'Company'],
    [`Record the Actual Closing Date on the Operating Agreement signature page, and sign the Company blocks on documents 01, 04 and ${ruiaRange}`, `Chief Executive Officer; Chief Technology Officer on document ${RUPIA_FIRST}`],
    ['Issue Capital Contribution receipts', `Chief Executive Officer; Chief Technology Officer on document ${RECEIPT_FIRST}`],
    [`Issue the Class B Units to Brock Smith, sign the Class B Unit Issuance Record (document ${BROCK_DOC}) and deliver that record to him within 10 days`, 'Chief Executive Officer'],
    ['Update Founder Capital Contribution Ledger', 'Company'],
    ['Update Official Unit Ledger, including the Class B entry and the Reserved Units', 'Company'],
    ['Update Capitalization Table', 'Company'],
    ['Update Founder Equity and Vesting Ledger', 'Company'],
    ['Update Members\' Capital Accounts and accounting records', 'Company'],
    ['Sign the Company signature blocks on the remaining record-book documents', 'Chief Executive Officer'],
    ['Sign Company Officer Certificate after all contributions are recorded and issuances are complete', 'Chief Executive Officer'],
    ['Open the Company bank account at Chase under the Banking Resolution and record the last four digits in the Company Account Schedule', 'Chief Executive Officer'],
    ['Within 60 days after the Actual Closing Date, document any other amount JGN paid for the Company before that date', 'JGN Media LLC'],
    ['Keep the executed record book, a copy of the Talent Agreement and JGN\'s payment records, and complete Company records', 'Company'],
  ];
  const others = FOUNDERS.filter(f => f !== CEO && f !== CTO);
  const body = EFF + `<h2>1. CLOSING CHECKLIST</h2>` +
  tbl(['Step', 'Document or action', 'Responsible signer', 'Date completed'], steps.map((s, i) => [String(i + 1), s[0], s[1], ''])) +
  `<h2>2. SIGNATURE INDEX</h2>` +
  tbl(['Signer', 'Capacity', 'Documents requiring signature'], [
    [nbName(CEO), 'Class A Member; CEO; Company authorized signer; JGN member; JGN Chief Executive Officer', `Operating Agreement, Organizational Consent, FMV Memorandum, Founder PIIA, RUIA (document ${ruiaOf(CEO)}), JGN Member Consent, JGN Agreement for both the Company and JGN Media LLC, First Amendment to the Talent Agreement for both the Company and JGN Media LLC, the Company signature block in documents 00, 01, 04 through 19, 21 through 24, ${RUPIA_FIRST + 1} through ${TALENT_AMEND_DOC} and ${RECEIPT_FIRST + 1} through ${RECEIPT_LAST}, receipt acknowledgment (document ${receiptOf(CEO)}) if requested`],
    [nbName(CTO), 'Class A Member; CTO', `Operating Agreement, Organizational Consent, FMV Memorandum, Founder PIIA, RUIA (document ${ruiaOf(CTO)}), Company countersignature on the Chief Executive Officer's RUIA and receipt (documents ${RUPIA_FIRST} and ${RECEIPT_FIRST})`],
  ].concat(others.map(f => [nbName(f), `Class A Member; ${f.short}; JGN member`, `Operating Agreement, Organizational Consent, FMV Memorandum, Founder PIIA, RUIA (document ${ruiaOf(f)}), JGN Member Consent, receipt acknowledgment (document ${receiptOf(f)}) if requested`]))
  .concat([[nbName(BROCK), 'Class B Member; Contractor under the Talent Agreement', `First Amendment to the Talent Agreement (document ${TALENT_AMEND_DOC}), which contains his joinder to the Operating Agreement. He signs nothing else. He receives a copy of the Operating Agreement before he signs and document ${BROCK_DOC} after the closing.`],
           ['JGN Media LLC', `Contracting entity; ${CEO.name} as Chief Executive Officer`, 'JGN Agreement; First Amendment to the Talent Agreement']])) +
  `<p class="note">RUIA means Restricted Unit Issuance Agreement. FMV Memorandum means the Founder Equity Fair Market Value Determination Memorandum. Organizational Consent means the Initial Member and Organizational Written Consent. Founder PIIA means the Founder Proprietary Information, IP Assignment and Data Security Agreement. JGN Agreement means the JGN Media LLC Platform Contribution, Brand License, Funding and Account Transition Agreement. JGN Member Consent means the JGN Member Consent Approving Nosebleed Agreement. The Chief Technology Officer countersigns the Chief Executive Officer's RUIA and receipt for the Company so that the Chief Executive Officer does not sign both sides of his own documents.</p>` + coSig();
  return doc(21, 'CLOSING CHECKLIST AND SIGNATURE INDEX', body);
}

// 22 Organization and Governance Summary
function doc22() {
  const body = DEF_ONLY +
  `<p>The Company is a Delaware member-managed limited liability company. There is no separate manager body. Class A Members approve Major Decisions and officers operate inside delegated lanes and authority thresholds. The Class B Member holds a non-voting economic interest.</p>` +
  kv([['Legal name', CO], ['Formed', 'Delaware, ' + FORMED], ['Delaware file number', DEFILE], ['EIN', EIN], ['Registered agent', RA], ['Principal business office', ADDR], ['Authorized Units', num(AUTH_UNITS) + ' (' + num(CLASS_A) + ' Class A and ' + num(CLASS_B) + ' Class B issued; ' + num(RESERVE) + ' reserved)']]) +
  tbl(['Layer', 'Persons', 'Authority'], [
    ['Class A Members', FOUNDERS_AND, `Ownership, voting, Major Decisions, amendments, Change of Control, governance review and other Member approvals under the Operating Agreement, including the meeting, participation and responsiveness standards in Section 4.5. Every approval requires ${VP} of outstanding Class A Units, which on the initial capitalization means any four of the five Founders. A Change of Control, any issuance of equity, any amendment of the Operating Agreement and any change of the Chief Executive Officer also require the consent of ${CEO.name} while he is in Continuous Service (Section 5.7). A matter about one Member (Cause, Disability, the Company's purchase rights and the other matters the Operating Agreement measures by Disinterested Ownership) instead requires at least three disinterested Members holding at least ${DVP} of the Disinterested Ownership, which means any three of the other four Founders.`],
    ['Contributing Founders', CONTRIB_AND, `The four members of JGN, who funded the Company through JGN. Each holds a Capital Contribution of ${APPROX_EACH}, returned first on any distribution.`],
    ['Service Founder', SERVICE.name, 'Holds Class A Units issued for services as a profits interest; votes like every other Founder; no interest in JGN.'],
    ['Class B Member', BROCK.name, 'Non-voting, fully vested profits interest issued under the Talent Agreement; joined the Operating Agreement through the Talent Amendment; services and compensation governed by the Talent Agreement.'],
    ['Chief Executive Officer', CEO.name, 'Executive leadership, Company signatures, sole bank signer, spending up to $5,000 without further approval; Tax Representative.'],
    ['Other officers', FOUNDERS.slice(1).map(f => `${f.name} (${f.office})`).join(', '), 'Officer-lane authority; spending up to $2,000 in lane without further approval.'],
    ['JGN Media LLC', 'Separate New York entity owned 25% each by ' + JGN_AND, 'Owns the Nosebleed Sports brand and the Social Accounts and receives their revenue; assigns the Platform Assets to the Company; licenses the brand and promotes the Platform under the JGN Agreement; funds the Company until the Self-Sufficiency Date as capital of its four members; not a Member.'],
    ['Reserved Units', num(RESERVE) + ' Units (' + fdPct(RESERVE) + ' fully diluted)', 'Unissued; reserved for future strategic partners and Milestone Units; issuable only as a Major Decision (strategic partners) or when earned (Milestone Units).'],
  ], 'w') + coSig();
  return doc(22, 'ORGANIZATION AND GOVERNANCE SUMMARY', body);
}

// 23 Capitalization Reconciliation Report
function doc23() {
  const per = FOUNDERS.map(f => `<h3>${f.name}</h3>` + kv([['Units', num(f.units) + ' Class A Units'], ['Percentage Interest', outPct(f.units)], ['Voting Interest', votePct(f.units)], ['Fully Diluted Percentage', fdPct(f.units)], ['Consideration', f.jgn ? 'Capital Contribution through JGN' : 'Services (profits interest)'], ['Capital Contribution', f.jgn ? APPROX_EACH : 'None'], ['Capital Account Credit', f.jgn ? APPROX_EACH : '$0'], ['Opening Unreturned Capital', f.jgn ? APPROX_EACH : '$0'], ['Immediately Vested', num(vested(f))], ['Restricted', num(vested(f))]], 'kv2')).join('');
  const brock = `<h3>${BROCK.name}</h3>` + kv([['Units', num(CLASS_B) + ' Class B Units'], ['Percentage Interest', outPct(CLASS_B)], ['Voting Interest', 'None'], ['Fully Diluted Percentage', fdPct(CLASS_B)], ['Consideration', 'Services under the Talent Agreement (profits interest)'], ['Capital Contribution', 'None'], ['Capital Account Credit', '$0'], ['Vesting', 'Fully vested on issuance']], 'kv2');
  const body = EFF + per + brock +
  tbl(['Item', 'Total'], [['Authorized Units', num(AUTH_UNITS)], ['Issued Class A Units', num(CLASS_A)], ['Issued Class B Units', num(CLASS_B)], ['Outstanding Units', num(OUTSTANDING)], ['Reserved Units (unissued)', num(RESERVE)], ['Total Percentage Interests', '100%'], ['Total Voting Interests', '100%'], ['Total Fully Diluted Percentages (including Reserved Units)', '100%'], ['Aggregate JGN Contribution through the Actual Closing Date', APPROX_TOTAL], ['Aggregate Capital Contributions', APPROX_TOTAL], ['Aggregate capital credited to Members\' Capital Accounts', APPROX_TOTAL], ['Aggregate Unreturned Capital', APPROX_TOTAL], ['Total company equity FMV', APPROX_TOTAL], ['Cash paid for Units', 'None'], ['Immediately vested Class A Units', num(CLASS_A / 2)], ['Restricted Class A Units over 48 months', num(CLASS_A / 2)], ['Vested Class B Units', num(CLASS_B)], ['Monthly vesting', '1/48 of each Founder\'s restricted Units monthly, with final installment true-up under Operating Agreement Section 6.2.']]) +
  `<p>The listed expenses total ${money(HIST_TOTAL)} (${HIST.map(h => money(h.amount)).join(' + ')}); ${money(HIST_TOTAL)} divided among the four Contributing Founders is ${money(CONTRIB_EACH)} each; the aggregate JGN Contribution, the aggregate Capital Contributions, the aggregate capital credited to Members' Capital Accounts, the aggregate Unreturned Capital and the total company equity FMV are the same amount; issued Class A Units (${num(CLASS_A)}) plus issued Class B Units (${num(CLASS_B)}) plus Reserved Units (${num(RESERVE)}) equal exactly ${num(AUTH_UNITS)} authorized Units; Percentage Interests total exactly 100% of the ${num(OUTSTANDING)} outstanding Units; and Voting Interests total exactly 100% of the ${num(CLASS_A)} outstanding Class A Units.</p>` + coSig();
  return doc(23, 'CAPITALIZATION RECONCILIATION REPORT', body);
}

// 24 Record Book Certification
function doc24() {
  const body = EFF +
  tbl(['Area', 'Record'], [
    ['Capitalization', `This record book documents ${num(AUTH_UNITS)} authorized Units; ${num(CLASS_A)} Class A Units issued to five Founders (${FOUNDERS.map(f => fdPct(f.units)).join(' / ')} fully diluted); ${num(CLASS_B)} Class B Units (${fdPct(CLASS_B)} fully diluted) issued to Brock Smith; ${num(RESERVE)} Reserved Units (${fdPct(RESERVE)}) unissued; and a total equity FMV of ${APPROX_TOTAL}.`],
    ['Founder issuance structure', `The four Contributing Founders receive Class A Units for Capital Contributions of ${APPROX_EACH} each, made through JGN Media LLC, which paid every Company and Platform expense. The Service Founder receives Class A Units for services as a profits interest. No Founder pays cash, gives a note or owes a purchase price for Units.`],
    ['Class B issuance', 'Brock Smith\'s Class B Units are issued fully vested as profits interests under the Talent Agreement, as amended by the First Amendment included in this record book, and Operating Agreement Section 3.7(b); Milestone Units, if earned, are issued from the Reserved Units up to a cumulative 5%.'],
    ['Historical expenses and funding', `JGN Media LLC paid every historical operating expense, ${APPROX_TOTAL} from May through November 2026, as itemized in the Historical Company Operating Expense and JGN Contribution Schedule and Schedule C to the Operating Agreement. That amount is capital of the Contributing Founders, not a loan; it is returned first on any distribution and is owed by no Member.`],
    ['Company identifiers', `Formation date ${FORMED}, Delaware file number ${DEFILE}, EIN ${EIN}, registered agent and principal business office are recorded in the Operating Agreement and the record book.`],
    ['Bank accounts', 'The Company has no bank account on the date this record book was prepared; the Banking Resolution authorizes the Chief Executive Officer, as sole signer, to open one at Chase, to be recorded in the Company Account Schedule.'],
    ['Governance', `Member-managed Delaware LLC structure, officer lanes, a ${VP} Class A approval threshold, a ${DVP} threshold among at least three disinterested Members for matters about one Member, the consent right of ${CEO.name} over a sale, new equity, amendments and the office of Chief Executive Officer (Operating Agreement Section 5.7), and a rule that silence never counts as approval (Operating Agreement Sections 5.2 and 5.3), Member meeting and participation standards (Operating Agreement Section 4.5), vesting with full acceleration if a buyer ends a Founder's service (Operating Agreement Section 6.12), transfer restrictions, repurchase terms, the Reserved Units and JGN's ownership are documented.`],
    ['Brand and audience', 'The Nosebleed Sports brand and the Social Accounts are owned by JGN Media LLC; the Company holds the exclusive, perpetual, royalty-free, transferable Brand License in the Field and the benefit of the promotion covenant under the JGN Agreement.'],
    ['IP chain of title', 'Founder PIIA, JGN Agreement, JGN Member Consent, Talent Agreement, IP Assignment Schedule and Chain of Title Register, Company Account Schedule and acquisition-cooperation obligations are included in or referenced by this record book.'],
    ['JGN authority', `JGN Media LLC is owned 25% each by ${JGN_AND}; all four approve the JGN Agreement in the JGN Member Consent; ${CEO.name} signs the JGN Agreement and the First Amendment to the Talent Agreement for JGN and for the Company as Chief Executive Officer of each, under unanimous consents on both sides.`],
    ['Tax responsibility', 'Each Member bears responsibility for that Member\'s own tax position with respect to the Units; the Company provides no tax advice.'],
  ], 'w') +
  `<p>This certification records what this record book contains. It is not a legal opinion, tax opinion, valuation opinion, fairness opinion or audit opinion.</p>` + coSig();
  return doc(24, 'RECORD BOOK CERTIFICATION', body);
}

module.exports = { doc14, doc15, doc16, doc17, doc18, doc19, doc20, doc21, doc22, doc23, doc24 };
